  "tool": "kmp_write_memory",
  "save_as": "identity",
  "arguments": {
    "about": "example:guide:incident-support",
    "intent": "record_observation",
    "actor": "guide-writer",
    "source_kind": "human",
    "idempotency_key": "guide-distributed:identity:v1",
    "scope": {
      "process": "atlas-incident-review"
    },
